mapper.select:
SELECT
    bb.bill_id AS billId,
    bbd.item_type AS itemType,
    bbd.item_id AS itemId,
    bbd.executor_id AS executorId,
    /*项目应收*/
    (bbd.quantity*bbd.price-bbd.discount_amount) AS receivableWorkload,
    /*项目数量*/
    bbd.quantity AS quantity,
    /*项目补入*/
    bbd.coupon_workload AS couponWorkload,

    /*账单总已收*/
        IFNULL(bbp.received_amount,0) AS totalReceivedWorkload,

    /*项目已收*/
    bbd.received_amount AS receivedWorkload,
    /*账单总应收*/
    bb.actual_amount AS actualWorkload
FROM base_bill_detail bbd
LEFT JOIN base_bill bb ON bb.bill_id = bbd.bill_id

    INNER JOIN (
        SELECT SUM(bbp.received_amount) AS received_amount, bbp.bill_id FROM base_bill_pay bbp
        WHERE DATE_FORMAT(bbp.payee_date,'%Y%m%d')=#{payeeDate}
        GROUP BY bbp.bill_id
    ) bbp ON bbp.bill_id = bb.bill_id


    AND bb.bill_date is not null
    AND bb.org_id = #{orgId}

        AND DATE_FORMAT(bb.bill_date, '%Y%m%d')  = #{billDate}


        AND DATE_FORMAT(bb.privilege_date, '%Y%m%d')  = #{privilegeDate}

    AND bbd.executor_id in

        #{item}

SELECT bbp.bill_id AS billId, DATE_FORMAT(bbp.payee_date, '%Y%m%d') AS billDate, bbpd.principal_amount + bbpd.bonus_amount AS freePaymentWorkload FROM base_bill_pay_detail bbpd INNER JOIN base_bill_pay bbp ON bbpd.bill_pay_id = bbp.bill_pay_id
AND bbpd.type = 2 AND bbpd.account_item_id in (23,26) AND exists ( SELECT bb.bill_id FROM base_bill bb INNER JOIN base_bill_detail bbd ON bbd.bill_id = bb.bill_id
bb.bill_id = bbp.bill_id AND bb.bill_date is not null AND bbd.executor_id > 0
AND bbd.org_id = #{query.orgId}
AND bbd.executor_id in
#{item}
)
AND DATE_FORMAT(bbp.payee_date, '%Y%m%d') between #{query.sDateInt} and #{query.eDateInt}
